const normalizeMasterName = (value: string) => value.toLowerCase()
  .replace(/\b(gms?|grams?|kgs?|kilograms?|pcs?|pieces?|packs?|boxes?)\b/g, ' ')
  .replace(/\b\d+(?:\.\d+)?\b/g, ' ')
  .replace(/[^a-z0-9]+/g, ' ')
  .trim().replace(/\s+/g, ' ');

const externalByName = new Map(externalItemMaster.map(item => [normalizeMasterName(item.name), item]));

export function enrichProductsFromItemMaster(products: Product[]): Product[] {
  return products.map(product => {
    const baseName = product.name.split(' · ')[0];
    const external = externalByName.get(normalizeMasterName(baseName));
    if (!external) return product;
    return { ...product, externalItemCode: external.itemCode, externalShortName: external.shortName, externalCategory: external.majorCategory, externalGst: external.gstTax, externalHsn: external.hsn || product.hsn };
  });
}

export function mergeImportedRawMaterials(core: Ingredient[]): Ingredient[] {
  const importedByName = new Map(importedRawMaterials.map(item => [normalizeMasterName(item.name), item]));
  const coreNames = new Set(core.map(item => normalizeMasterName(item.name)));
  const enriched = core.map(item => {
    const imported = importedByName.get(normalizeMasterName(item.name));
    return imported ? { ...imported, ...item, unitCost: imported.unitCost || item.unitCost } : item;
  });
  return [...enriched, ...importedRawMaterials.filter(item => !coreNames.has(normalizeMasterName(item.name)))];
}

